1	/*!
2	 * \file tl/ir.cc
3	 * \brief Extension for the tvm script frontend.
4	 *
5	 */
6	
7	#include "./transform/common/attr.h"
8	#include "op/builtin.h"
9	#include "support/check.h"
10	#include <tvm/ir/cast.h>
11	#include <tvm/runtime/logging.h>
12	#include <tvm/tirx/stmt.h>
