20	namespace tvm {
21	namespace tl {
22	
23	using namespace script::ir_builder::tirx;
24	using namespace ffi;
25	
26	// Build a ForFrame that emits a target-neutral kThreadBinding loop for one
27	// kernel-launch dimension. The launch nest is materialized into the
28	// target-specific form (thread_extent AttrStmt on GPU, serial For on CPU) by
29	// the tl.MaterializeKernelLaunch pass once the Target is known at compile
30	// time.
31	static ForFrame MakeThreadBindingFrame(const std::string &name,
32	                                       const String &thread_tag,
33	                                       const PrimExpr &extent) {
34	  using namespace tvm::tirx;
35	  Var var = Var(name, extent->dtype);
36	  ObjectPtr<ForFrameNode> n = make_object<ForFrameNode>();
37	  n->vars.push_back(var);
38	  n->doms.push_back(Range(make_const(extent->dtype, 0), extent));
39	  n->f_make_for_loop =
40	      [thread_tag](const Array<Var> &vars, const Array<Range> &doms,
41	                   const Array<Optional<PrimExpr>> &steps, Stmt body) -> Stmt {
42	    ICHECK_EQ(vars.size(), 1);
43	    ICHECK_EQ(doms.size(), 1);
44	    IterVar iter_var(Range{nullptr}, Var(thread_tag, vars[0]->dtype),
45	                     IterVarType::kThreadIndex, thread_tag);
46	    Optional<PrimExpr> step =
47	        !steps.empty() ? steps[0] : Optional<PrimExpr>(std::nullopt);
48	    return For(vars[0], doms[0]->min, doms[0]->extent, ForKind::kThreadBinding,
49	               body,
50	               /*thread_binding=*/iter_var,
51	               /*annotations=*/Map<String, Any>{},
52	               /*step=*/step);
53	  };
54	  return ForFrame(n);
55	}
56	
57	ForFrame ParallelFor(const Array<PrimExpr> &extents,
58	                     const Map<String, Any> &annotations) {
59	  using namespace tvm::tirx;
60	  ObjectPtr<ForFrameNode> n = make_object<ForFrameNode>();
61	  n->vars.reserve(extents.size());
62	  n->doms.reserve(extents.size());
63	  for (const auto &extent : extents) {
64	    DataType dtype = extent.dtype();
65	    n->vars.push_back(Var("v", extent.dtype()));
66	    n->doms.push_back(Range(make_const(dtype, 0), extent));
67	  }
68	  n->f_make_for_loop =
69	      [annotations](const Array<Var> &vars, const Array<Range> &doms,
70	                    const Array<Optional<PrimExpr>> &steps, Stmt body) -> Stmt {
71	    ICHECK_EQ(vars.size(), doms.size());
72	    int n = vars.size();
73	    for (int i = n - 1; i >= 0; --i) {
74	      Range dom = doms[i];
75	      Var var = vars[i];
76	      Optional<PrimExpr> step =
77	          i < steps.size() ? steps[i] : Optional<PrimExpr>(std::nullopt);
78	      // Only attach annotations to the outermost parallel loop.
79	      // Rationale: In TileLang's design, inner loops cannot govern or annotate
80	      // their outer loops, while the outermost loop can manage and transform
81	      // the entire nested region. Placing the layout on the outermost loop
82	      // lets lowering/validators reason about and rewrite the whole nest.
83	      // Layout annotations (like parallel_loop_layout) and other hints are
84	      // read from the outermost loop.
85	      Map<String, Any> loop_annotations;
86	      if (i == 0) {
87	        loop_annotations = annotations;
88	      }
89	      body = For(var, dom->min, dom->extent, ForKind::kParallel, body,
90	                 /*thread_binding=*/std::nullopt,
91	                 /*annotations=*/loop_annotations,
92	                 /*step=*/step);
93	    }
94	    return body;
95	  };
96	  return ForFrame(n);
97	}
98	
99	ForFrame PipelinedFor(PrimExpr start, const PrimExpr &stop, int num_stages,
100	                      const Array<PrimExpr> &order,
101	                      const Array<PrimExpr> &stages,
102	                      const Array<Array<PrimExpr>> &sync,
103	                      const Array<Array<PrimExpr>> &groups) {
104	  using namespace tvm::tirx;
105	  ObjectPtr<ForFrameNode> n = make_object<ForFrameNode>();
106	  DataType dtype = stop.dtype();
107	  n->vars.push_back(Var("v", dtype));
108	  n->doms.push_back(Range(std::move(start), stop));
109	  n->f_make_for_loop = [=](const Array<Var> &vars, const Array<Range> &doms,
110	                           const Array<Optional<PrimExpr>> &steps,
111	                           Stmt body) -> Stmt {
112	    ICHECK_EQ(vars.size(), doms.size());
113	    int n = vars.size();
114	    ICHECK(n == 1);
115	    Map<String, Any> anno;
116	    if (num_stages > 0)
117	      anno.Set("num_stages", PrimExpr(num_stages));
118	    if (!order.empty())
119	      anno.Set("tl_pipeline_order", order);
120	    if (!stages.empty())
121	      anno.Set("tl_pipeline_stage", stages);
122	    if (!groups.empty())
123	      anno.Set("tl_pipeline_group", groups);
124	    Optional<PrimExpr> step =
125	        !steps.empty() ? steps[0] : Optional<PrimExpr>(std::nullopt);
126	    body = For(vars[0], doms[0]->min, doms[0]->extent, ForKind::kSerial, body,
127	               /*thread_binding=*/std::nullopt, /*annotations=*/anno,
128	               /*step=*/step);
129	    return body;
130	  };
131	  return ForFrame(n);
132	}
133	
134	ForFrame PersistentFor(const Array<PrimExpr> &domain, const PrimExpr &wave_size,
135	                       const PrimExpr &index, PrimExpr group_size) {
136	  using namespace tvm::tirx;
137	  ICHECK(!domain.empty());
138	  ObjectPtr<ForFrameNode> n = make_object<ForFrameNode>();
139	  n->vars.reserve(domain.size());
140	  n->doms.reserve(domain.size());
141	  PrimExpr domain_size = domain[0];
142	  for (int i = 1; i < domain.size(); i++) {
143	    domain_size *= domain[i];
144	  }
145	
146	  PrimExpr last_extent = domain[domain.size() - 1];
147	  group_size =
148	      max(make_const(group_size.dtype(), 1), min(group_size, last_extent));
149	  Array<PrimExpr> grouped_domain;
150	  grouped_domain.push_back(ceildiv(last_extent, group_size));
151	  for (int i = 0; i < domain.size() - 1; ++i) {
152	    grouped_domain.push_back(domain[i]);
153	  }
154	  grouped_domain.push_back(group_size);
155	  PrimExpr padded_domain_size = grouped_domain[0];
156	  for (int i = 1; i < grouped_domain.size(); ++i) {
157	    padded_domain_size *= grouped_domain[i];
158	  }
159	
160	  auto waves = ceildiv(padded_domain_size, wave_size);
161	  auto loop_var = Var("w", waves.dtype());
162	  Array<Var> coord_vars;
163	
164	  for (int i = 0; i < domain.size(); ++i) {
165	    DataType dtype = domain[i].dtype();
166	    Var coord("v" + std::to_string(i), dtype);
167	    coord_vars.push_back(coord);
168	    n->vars.push_back(coord);
169	    n->doms.push_back(Range(make_const(dtype, 0), domain[i]));
170	  }
171	
172	  n->f_make_for_loop = [=](const Array<Var> &vars, const Array<Range> &doms,
173	                           const Array<Optional<PrimExpr>> &steps,
174	                           Stmt body) -> Stmt {
175	    ICHECK_EQ(vars.size(), doms.size());
176	    Map<String, Any> anno;
177	    Array<PrimExpr> idxs(grouped_domain.size(), PrimExpr());
178	    PrimExpr rem = loop_var * wave_size + index;
179	
180	    for (int i = grouped_domain.size() - 1; i >= 1; --i) {
181	      idxs.Set(i, truncmod(rem, grouped_domain[i]));
182	      rem = truncdiv(rem, grouped_domain[i]);
183	    }
184	    idxs.Set(0, rem);
185	    PrimExpr last_coord =
186	        idxs[0] * group_size + idxs[grouped_domain.size() - 1];
187	    PrimExpr in_range = last_coord < domain[domain.size() - 1];
188	    auto out_if = tvm::tirx::IfThenElse(
189	        padded_domain_size <= (loop_var * wave_size + index),
190	        tvm::tirx::Evaluate(
191	            tvm::tirx::Call(DataType::Handle(), tvm::tl::loop_break(), {})),
192	        Stmt());
193	    Stmt guarded_body = tvm::tirx::IfThenElse(in_range, body, Stmt());
194	
195	    arith::Analyzer analyzer;
196	    Stmt new_body = guarded_body;
197	    if (analyzer.CanProveGreaterEqual(waves, 2)) {
198	      new_body = SeqStmt({out_if, guarded_body});
199	    }
200	    Optional<PrimExpr> step =
201	        !steps.empty() ? steps[0] : Optional<PrimExpr>(std::nullopt);
202	    Stmt outer = For(loop_var, 0, waves, ForKind::kSerial, new_body,
203	                     /*thread_binding=*/std::nullopt, /*annotations=*/anno,
204	                     /*step=*/step);
205	    for (int i = 0; i < vars.size() - 1; ++i) {
206	      outer = SeqStmt({tirx::Bind(vars[i], idxs[i + 1]), outer});
207	    }
208	    outer = SeqStmt({tirx::Bind(vars[vars.size() - 1], last_coord), outer});
209	    return outer;
210	  };
211	
212	  return ForFrame(n);
213	}
