215	/*!
216	 * \brief A frame that represents a kernel launch.
217	 *
218	 * \sa KernelLaunchFrameNode
219	 */
220	class KernelLaunchFrameNode : public TIRFrameNode {
221	public:
222	  Array<TIRFrame> frames;
223	
224	  static void RegisterReflection() {
225	    namespace refl = reflection;
226	    refl::ObjectDef<KernelLaunchFrameNode>().def_ro(
227	        "frames", &KernelLaunchFrameNode::frames);
228	  }
229	
230	  TVM_FFI_DECLARE_OBJECT_INFO_FINAL("tl.KernelLaunchFrame",
231	                                    KernelLaunchFrameNode, TIRFrameNode);
232	
233	public:
234	  TVM_DLL void EnterWithScope() final {
235	    for (auto frame = frames.begin(); frame != frames.end(); ++frame)
236	      (*frame)->EnterWithScope();
237	  }
238	  /*!
239	   * \brief The method called when exiting RAII scope.
240	   * \sa tvm::support::With
241	   */
242	  TVM_DLL void ExitWithScope() final {
243	    for (auto frame = frames.rbegin(); frame != frames.rend(); ++frame)
244	      (*frame)->ExitWithScope();
245	  }
246	};
247	
248	/*!
249	 * \brief Managed reference to KernelLaunchFrameNode.
250	 *
251	 * \sa KernelLaunchFrameNode
252	 */
253	class KernelLaunchFrame : public TIRFrame {
254	public:
255	  explicit KernelLaunchFrame(ObjectPtr<KernelLaunchFrameNode> data)
256	      : TIRFrame(UnsafeInit{}) {
257	    ICHECK(data != nullptr);
258	    data_ = std::move(data);
259	  }
260	  TVM_FFI_DEFINE_OBJECT_REF_METHODS_NOTNULLABLE(KernelLaunchFrame, TIRFrame,
261	                                                KernelLaunchFrameNode);
262	};
263	
264	KernelLaunchFrame KernelLaunch(const Array<PrimExpr> &grid_size,
265	                               const Optional<Array<PrimExpr>> &block_size_opt,
266	                               const Map<String, Any> &attrs) {
267	  ObjectPtr<KernelLaunchFrameNode> n = make_object<KernelLaunchFrameNode>();
268	
269	  auto block_size = block_size_opt.value_or(Array<PrimExpr>());
270	  ICHECK(grid_size.size() <= 3);
271	  ICHECK(block_size.size() <= 3);
272	
273	  static const char *kBlockVarNames[3] = {"bx", "by", "bz"};
274	  static const char *kBlockTags[3] = {"blockIdx.x", "blockIdx.y", "blockIdx.z"};
275	  static const char *kThreadVarNames[3] = {"tx", "ty", "tz"};
276	  static const char *kThreadTags[3] = {"threadIdx.x", "threadIdx.y",
277	                                       "threadIdx.z"};
278	
279	  for (size_t i = 0; i < grid_size.size(); i++) {
280	    n->frames.push_back(
281	        MakeThreadBindingFrame(kBlockVarNames[i], kBlockTags[i], grid_size[i]));
282	  }
283	  for (size_t i = 0; i < block_size.size(); i++) {
284	    n->frames.push_back(MakeThreadBindingFrame(kThreadVarNames[i],
285	                                               kThreadTags[i], block_size[i]));
286	  }
287	
288	  auto empty_block = tvm::script::ir_builder::tirx::Block(DeviceMainBlockName);
289	  empty_block->reads = Array<tvm::tirx::BufferRegion>();
290	  empty_block->writes = Array<tvm::tirx::BufferRegion>();
291	  Map<String, Any> block_annotations =
292	      attrs.defined() ? attrs : Map<String, Any>{};
293	  empty_block->annotations = block_annotations;
294	  n->frames.push_back(empty_block);
295	
296	  return KernelLaunchFrame(n);
297	}
298	
299	TVM_FFI_STATIC_INIT_BLOCK() {
300	  namespace refl = reflection;
301	  refl::GlobalDef()
302	      .def("tl.Parallel", ParallelFor)
303	      .def("tl.Pipelined", PipelinedFor)
304	      .def("tl.Persistent", PersistentFor)
305	      .def("tl.KernelLaunch", KernelLaunch);
306	}
