308	class WarpSpecializeFrameNode : public TIRFrameNode {
309	public:
310	  Array<TIRFrame> frames;
311	
312	  static void RegisterReflection() {
313	    namespace refl = reflection;
314	    refl::ObjectDef<WarpSpecializeFrameNode>().def_ro(
315	        "frames", &WarpSpecializeFrameNode::frames);
316	  }
317	
318	  TVM_FFI_DECLARE_OBJECT_INFO_FINAL("tl.WarpSpecializeFrame",
319	                                    WarpSpecializeFrameNode, TIRFrameNode);
320	
321	public:
322	  TVM_DLL void EnterWithScope() final {
323	    for (auto frame = frames.begin(); frame != frames.end(); ++frame)
324	      (*frame)->EnterWithScope();
325	  }
326	  /*!
327	   * \brief The method called when exiting RAII scope.
328	   * \sa tvm::support::With
329	   */
330	  TVM_DLL void ExitWithScope() final {
