336	class WarpSpecializeFrame : public TIRFrame {
337	public:
338	  explicit WarpSpecializeFrame(ObjectPtr<WarpSpecializeFrameNode> data)
339	      : TIRFrame(UnsafeInit{}) {
340	    ICHECK(data != nullptr);
341	    data_ = std::move(data);
342	  }
343	  TVM_FFI_DEFINE_OBJECT_REF_METHODS_NOTNULLABLE(WarpSpecializeFrame, TIRFrame,
344	                                                WarpSpecializeFrameNode);
345	};
346	
347	WarpSpecializeFrame WarpSpecialize(const Array<IntImm> &warp_group_ids,
348	                                   const PrimExpr &thread_idx,
349	                                   int warp_group_size = 128) {
350	  ObjectPtr<WarpSpecializeFrameNode> n = make_object<WarpSpecializeFrameNode>();
351	  PrimExpr condition;
352	  std::vector<int> warp_groups;
353	  warp_groups.reserve(warp_group_ids.size());
354	  for (int i = 0; i < warp_group_ids.size(); i++) {
355	    warp_groups.push_back(Downcast<IntImm>(warp_group_ids[i])->value);
356	  }
357	  std::sort(warp_groups.begin(), warp_groups.end());
358	
359	  // Merge consecutive groups
360	  std::vector<std::pair<int, int>> merged;
361	  for (int group : warp_groups) {
362	    if (merged.empty() || group != merged.back().second) {
363	      merged.emplace_back(group, group + 1);
364	    } else {
365	      merged.back().second = group + 1;
366	    }
367	  }
368	
369	  for (const auto &[start, end] : merged) {
370	    PrimExpr min_bound = IntImm(thread_idx.dtype(), start) * warp_group_size;
371	    PrimExpr max_bound = IntImm(thread_idx.dtype(), end) * warp_group_size;
372	    PrimExpr range_cond = (thread_idx >= min_bound) && (thread_idx < max_bound);
373	
374	    if (condition.defined()) {
375	      condition = tirx::Or(condition, range_cond);
376	    } else {
377	      condition = range_cond;
378	    }
379	  }
380	  IfFrame if_frame = If(condition);
381	  AttrFrame attr_frame = Attr(Integer(0), "warp_specialize", Integer(1));
382	  n->frames.push_back(if_frame);
383	  n->frames.push_back(Then());
384	  n->frames.push_back(attr_frame);
385	  return WarpSpecializeFrame(n);
386	}
387	
388	TVM_FFI_STATIC_INIT_BLOCK() {
389	  namespace refl = reflection;
390	  refl::GlobalDef()
391	      .def("tl.WarpSpecialize", WarpSpecialize)
392	      .def("tl.SideEffect", tirx::SideEffect);
393	  KernelLaunchFrameNode::RegisterReflection();
394	  WarpSpecializeFrameNode::RegisterReflection();
395	}
396	
397	} // namespace tl
398	} // namespace tvm
