1089	   * @brief Handle an Evaluate node, lowering a detected tile operator to TIR.
1090	   *
1091	   * This visit implementation detects whether the Evaluate node represents a
1092	   * tile operator invocation (via ParseOperator). If no tile operator is found
1093	   * or the call targets a global function, the node is delegated to the base
1094	   * visitor.
1095	   *
1096	   * When a tile operator is present, the method:
1097	   * - Builds a workspace-allocation callback that creates a dynamic shared
1098	   * buffer named "workspace" (storage scope "shared.dyn") and returns its write
1099	   *   access pointer.
1100	   * - Determines thread bounds for lowering from the analyzer's constant-int
1101	   *   information for thread_var_; if unavailable, a default range [0,1) is
1102	   * used.
1103	   * - Invokes tile_op->Lower(...) with LowerArgs containing target, thread
1104	   *   bounds, thread variable, the workspace callback, layout and buffer remap
1105	   *   maps, and the list of GEMM-involved buffer vars; the analyzer is passed
1106	   *   through for use during lowering.
1107	   *
1108	   * The lowered statement returned by the operator is then visited by the base
1109	   * IRMutatorWithAnalyzer and that result is returned.
1110	   *
1111	   * @return Stmt The (possibly transformed) statement after lowering or base
1112	   * visitor processing.
1113	   */
1114	  Stmt VisitStmt_(const AllocBufferNode *op) final {
1115	    auto buffer = op->buffer;
1116	    if (buffer_remap_.count(buffer)) {
1117	      auto node = Downcast<AllocBuffer>(IRMutatorWithAnalyzer::VisitStmt_(op));
1118	      node.CopyOnWrite()->buffer = buffer_remap_[buffer];
1119	      return std::move(node);
1120	    }
1121	    if (IsFragmentBuffer(buffer)) {
1122	      const auto *ptr_type =
1123	          TVM_TYPE_AS(buffer->data->type_annotation, PointerTypeNode);
1124	      Type new_type = PointerType(ptr_type->element_type, "local");
1125	      Var new_var;
1126	      if (var_remap_.count(buffer->data)) {
1127	        new_var = var_remap_[buffer->data];
1128	      } else {
1129	        new_var = Var(buffer->data->name_hint, new_type);
1130	        var_remap_.Set(buffer->data, new_var);
1131	      }
