1133	                     buffer->elem_offset, buffer->name, buffer->data_alignment,
1134	                     buffer->offset_factor, buffer->buffer_type);
1135	      buffer_remap_.Set(buffer, new_buf);
1136	      auto node = Downcast<AllocBuffer>(IRMutatorWithAnalyzer::VisitStmt_(op));
